import {renderAIChat,installAI,mountAI,resetAI} from './ai-chat.mjs?v=20261101-tournaments';
import {renderWorkspace,installWorkspace,mountWorkspace,releaseWorkspace,resetEvidence} from './workspace.mjs?v=20261101-tournaments';
import {renderLanding} from './landing.mjs';
import {freshState,parseState,dayKey,validProfile,makePlan,dailyLoad,summary,MODES,TEAMS,ROLES,FOCI} from './engine.mjs?v=20261101-tournaments';
import {renderProfilePanel,installProfilePanel,mountProfilePanel} from './profile-panel.mjs?v=20261101-tournaments';
import {renderTournamentJournal,installTournamentJournal} from './tournament-journal.mjs?v=20261101-tournaments';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M4 10h12m-5-5 5 5-5 5',home:'m3 9 7-6 7 6v9H3zm5 9v-6h4v6',plan:'M5 3h10v15H5zm3 4h4m-4 4h4m-4 4h3',chat:'M3 3h14v11H8l-5 4z',play:'M7 4v12l10-6z',chart:'M3 3v14h15M7 13V9m4 4V5m4 8V7',settings:'M10 3v2m0 10v2M3 10h2m10 0h2M5 5l1 1m8 8 1 1M5 15l1-1m8-8 1-1M13 10a3 3 0 1 1-6 0 3 3 0 1 1 6 0',check:'m4 10 4 4 8-9',close:'m5 5 10 10M15 5 5 15',upload:'M10 14V3m-4 4 4-4 4 4M3 13v4h14v-4',book:'M10 5C7 2 3 3 3 3v14s4-1 7 1c3-2 7-1 7-1V3s-4-1-7 2zm0 0v13',sun:'M10 2v2m0 12v2M2 10h2m12 0h2M4 4l2 2m8 8 2 2M4 16l2-2m8-8 2-2M13 10a3 3 0 1 1-6 0 3 3 0 1 1 6 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><path d="${paths[n]||paths.arrow}"/></svg>`;
const logo=`<a class="logo" href="#home"><img src="mark.svg" alt=""><span class="brand-name">FORTNITE<small>AI COACH</small></span><span style="color:var(--muted);font-size:9px;letter-spacing:0">α</span></a>`;
let state=freshState(),loadError=false,storageFailed=false,mediaUrl=null,editingCheckin=false,renderedDay=dayKey();
try{const s=localStorage.getItem('nextdrop.v1');if(s)state=parseState(s);}catch{loadError=true;}
function save(){try{localStorage.setItem('nextdrop.v1',JSON.stringify(state));return true;}catch{storageFailed=true;toast('Не удалось сохранить в браузере. Экспортируй данные в настройках.');return false;}}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const labels={dashboard:'Главная',plan:'Работа над игрой',coach:'AI-тренер',review:'Работа над игрой',journal:'Заметки и турниры',settings:'Профиль и данные'};
const navs=[['dashboard','home','Главная','С чего начать'],['plan','plan','Работа над игрой','Разобрать момент'],['coach','chat','AI-тренер','Обсудить вопрос'],['journal','book','Заметки и турниры','История результатов'],['settings','settings','Профиль','Данные игрока']];
function go(v){location.hash=v;}
function landing(){return renderLanding(state,logo,icon);}
function pagehead(title,sub){return `<div class="pagehead"><div><h1>${title}</h1><p>${sub}</p></div><span class="badge lime"><i class="dot"></i> МОЯ ПРАКТИКА</span></div>`;}
function dashboard(){
 const p=state.profile,day=dayKey(),saved=state.checkins[day],plan=saved?makePlan(p,saved):[],light=saved&&dailyLoad(saved)==='light';
 const minutes=plan.reduce((n,t)=>n+t.minutes,0);
 const checkin=saved&&!editingCheckin?`<div class="daily-saved"><span class="badge lime">ОТМЕЧЕНО НА ${esc(day)}</span><h3>${saved.sleep} ч сна · энергия ${saved.energy}/5 · ${saved.minutes||p.minutes} мин свободного времени</h3><p>${light?'Сегодня достаточно спокойного разбора без игровой нагрузки.':'Сегодня можно проверить одно изменение в игре.'} План: ${minutes} мин. Первый шаг — ${esc(plan[0]?.title)}.</p><div class="actions"><a class="btn" href="#plan">Открыть задачу →</a><button class="btn secondary" type="button" data-checkin-edit>Изменить отметку</button></div></div>`:`<form id="checkin-form"><p class="daily-date">Отметка на ${esc(day)}. Завтра начнёшь с новой; вчерашняя не переносится.</p><div class="field"><label for="sleep">Сколько часов ты спал?</label><input id="sleep" name="sleep" type="number" min="0" max="24" step="0.5" value="${saved?.sleep??''}" placeholder="Например, 7.5" required></div><div class="field"><label for="energy">Как оцениваешь энергию сейчас?</label><select id="energy" name="energy" required><option value="" ${!saved?'selected':''} disabled>Выбери от 1 до 5</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${saved?.energy===n?'selected':''}>${n} / 5${n<=2?' · мало сил':n===3?' · средне':' · много сил'}</option>`).join('')}</select></div><div class="field"><label for="today-minutes">Сколько времени есть сегодня?</label><select id="today-minutes" name="minutes" required><option value="" ${!saved?'selected':''} disabled>Выбери время</option>${[20,40,60,90].map(n=>`<option value="${n}" ${saved?.minutes===n?'selected':''}>${n} минут</option>`).join('')}</select></div><button class="btn" type="submit">Подобрать задачу на сегодня →</button></form>`;
 return `<div class="workspace"><div class="ws-heading"><div><h1>За работу, ${esc(p.nick)}.</h1><p>${esc(p.mode)} · ${esc(p.team)} · ${esc(p.focus)}</p></div></div><div class="grid-main"><section class="card"><span class="badge lime">ТВОЯ РАБОТА</span><h2>Разбери один эпизод и получи обратную связь</h2><p>Опиши момент, ответь на три точных вопроса и попроси AI-тренера оценить твою версию. Он отделит наблюдение от догадки и предложит одно проверяемое упражнение. После практики сравни результат с целью.</p><a class="btn" href="#plan">${state.cases?.length?'Продолжить разбор':'Начать разбор'} →</a><p class="fine">AI анализирует твой текст и данные профиля; видео и реплеи автоматически пока не смотрит.</p><a href="#journal">Открыть мои заметки →</a></section><section class="card daily-checkin"><span class="badge lime">СЕГОДНЯШНЯЯ НАГРУЗКА</span><h2>Как ты сегодня?</h2><p>Эти три ответа определят время и тип сегодняшней задачи. Если сил мало, вместо игровой практики получишь разбор без нагрузки.</p>${checkin}</section></div></div>`;
}
function planPage(){return renderWorkspace();}
function coachPage(){return renderAIChat();}
function reviewPage(){return renderWorkspace();}
function journalPage(){return renderTournamentJournal(state);}
function settingsPage(){const p=state.profile;return `${pagehead('Твой профиль','Данные, на которых строится первая версия плана.')}<div class="grid-main"><div class="stack"><section class="card"><div class="card-top"><h2>${esc(p.nick)}</h2><button class="btn secondary small" data-action="edit-profile">Изменить</button></div><div class="tagrow">${[p.mode,p.team,p.build,p.team==='Solo'?'Все роли':p.role,`${p.minutes} мин`].map(t=>`<span class="badge">${esc(t)}</span>`).join('')}</div><p>Фокус: ${esc(p.focus)}.</p></section><section class="card"><h3>Турнирные показатели</h3><p>Введённые тобой значения. Автоматическая проверка пока не подключена. Пустое поле означает «нет данных».</p><form id="stats-form"><div class="form-grid">${[['pr','Power Ranking'],['earnings','Призовые, USD'],['events','Турнирных сессий']].map(([k,l])=>`<div class="field"><label for="stat-${k}">${l}</label><input id="stat-${k}" name="${k}" type="number" min="0" max="1000000000" step="${k==='earnings'?'0.01':'1'}" value="${state.stats[k]??''}"></div>`).join('')}</div><button class="btn secondary small" type="submit">Сохранить показатели</button></form></section><section class="card"><h3>Ссылки на твои профили</h3><p>Сохраняются как ссылки для проверки. Страницы не скачиваются автоматически.</p><form id="links-form"><div class="field"><label for="tracker">Fortnite Tracker</label><input id="tracker" name="tracker" type="url" value="${esc(p.tracker||'')}" placeholder="https://fortnitetracker.com/fortnite/profile/…"></div><div class="field"><label for="osirion">Osirion</label><input id="osirion" name="osirion" type="url" value="${esc(p.osirion||'')}" placeholder="https://osirion.gg/…"></div><p id="links-error" class="error" role="alert"></p><button class="btn secondary small" type="submit">Сохранить ссылки</button></form>${[['tracker','Открыть Fortnite Tracker'],['osirion','Открыть Osirion']].filter(([k])=>safeProfileURL(p[k],k)).map(([k,t])=>`<a class="source-link" href="${esc(p[k])}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`).join('')}</section>${renderProfilePanel(state)}</div><aside class="stack"><section class="card"><h3>Сохранение и перенос</h3><p>Профиль, журнал и диалог хранятся только в этом браузере. Сделай резервную копию для переноса на другой девайс.</p><button class="btn secondary small" data-action="export">Экспортировать JSON</button><div class="field" style="margin-top:22px"><label for="import">Импортировать резервную копию</label><input type="file" id="import" accept="application/json,.json"></div><p class="fine">Импорт заменит текущий профиль после подтверждения. Медиафайлы в копию не входят.</p></section><section class="card"><h3>Состояние базы</h3><span class="badge amber">Требует проверки</span><p style="margin-top:15px">Мета сезона и автоматический монитор обновлений ещё не подключены. Сезонные советы отключены.</p><a class="source-link" href="https://www.fortnite.com/news" target="_blank" rel="noopener noreferrer">Официальные обновления ↗</a><a class="source-link" href="https://www.fortnite.com/competitive" target="_blank" rel="noopener noreferrer">Fortnite Competitive ↗</a></section><section class="card"><h3>Удаление данных</h3><p>Удалит профиль, диалог и журнал из этого браузера.</p><button class="btn danger small" data-action="reset">Удалить мои данные</button></section></aside></div>`;}
function safeProfileURL(value,type){if(!value)return false;try{const u=new URL(value);return u.protocol==='https:'&&[type==='tracker'?'fortnitetracker.com':'osirion.gg',type==='tracker'?'www.fortnitetracker.com':'www.osirion.gg'].includes(u.hostname)&&!u.username&&!u.password;}catch{return false;}}
function render(){if(renderedDay!==dayKey()){renderedDay=dayKey();editingCheckin=false;}releaseWorkspace();let route=location.hash.slice(1)||'home';const home=['home','how','principles','faq'].includes(route);if(!home&&!state.profile){location.hash='home';return;}if(mediaUrl){URL.revokeObjectURL(mediaUrl);mediaUrl=null;}if(home){$('#app').innerHTML=landing();if(route!=='home')requestAnimationFrame(()=>document.getElementById(route)?.scrollIntoView());}else{if(!labels[route])route='dashboard';const pages={dashboard,plan:planPage,coach:coachPage,review:reviewPage,journal:journalPage,settings:settingsPage};$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${logo}<div><p class="nav-label">ТВОЯ РАБОЧАЯ ЗОНА</p><nav class="sidenav">${navs.map(([id,i,l,hint])=>`<a href="#${id}" class="navitem ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(i)}<span class="nav-copy"><strong>${l}</strong><small>${hint}</small></span></a>`).join('')}</nav></div><div class="side-bottom"><span class="badge lime">FORTNITE AI COACH · ALPHA</span><p>Твоя работа.<br>Твой следующий шаг.</p><a href="#home">О проекте ↗</a></div></aside><main class="main"><header class="appbar"><span class="crumb">Рабочая зона / ${labels[route]}</span><a href="#home" class="mobile-brand">FORTNITE AI COACH ↗</a><div class="userchip"><span>${esc(state.profile.nick)}</span><a href="#settings" class="avatar" aria-label="Открыть профиль">${esc(state.profile.nick.slice(0,1).toUpperCase())}</a></div></header>${pages[route]()}</main></div>`;if(['plan','review'].includes(route))requestAnimationFrame(()=>mountWorkspace());if(route==='coach')requestAnimationFrame(()=>mountAI());if(route==='settings')requestAnimationFrame(()=>mountProfilePanel(state));}if(storageFailed)toast('Сохранение недоступно. Сделай экспорт данных.');}
let step=0,draft={};
function onboarding(edit=false){step=0;draft=edit?{...state.profile}:{nick:'',mode:'Battle Royale',team:'Solo',build:'Build',role:'IGL',focus:FOCI[0],minutes:40};renderOnboarding();$('#onboarding').showModal();}
const options=(key,values)=>`<div class="options">${values.map(v=>`<button type="button" class="option ${String(draft[key])===String(v)?'selected':''}" data-option="${key}" data-value="${v}" aria-pressed="${String(draft[key])===String(v)}">${typeof v==='number'?`${v} мин`:v}</button>`).join('')}</div>`;
function renderOnboarding(){const titles=['С чего начинаем?','Твоя роль в игре','На чём сосредоточимся?','План, который впишется в день'];const desc=['Никнейм нужен для профиля. Проверка Epic-аккаунта пока не выполняется.','Выбери формат, под который нужна практика. Обязанности внутри команды уточняются отдельно.','Не знаешь, что проседает? Выбери общий импрув — начнём с наблюдений за твоей игрой.','Выбери комфортное время на одну сессию. Позже учтём сегодняшнюю энергию.'];let content='';if(step===0)content=`<div class="field"><label for="nick">Твой Epic-никнейм</label><input id="nick" maxlength="32" autocomplete="nickname" value="${esc(draft.nick)}" placeholder="Как к тебе обращаться?" required></div><div class="field-label">Режим</div>${options('mode',MODES)}<div class="field-label">Строительство</div>${options('build',['Build','Zero Build'])}`;if(step===1)content=`<div class="field-label">Состав</div>${options('team',TEAMS)}${draft.team==='Solo'?'<div class="notice">В Solo ты принимаешь решения, файтишь и отвечаешь за собственную игру. Отдельную командную роль выбирать не нужно.</div>':`<div class="field-label">Твоя основная роль</div>${options('role',draft.team==='Duo'?['IGL','Фраггер']:ROLES)}<p class="fine">Саппорт в Trio рассматривается как второй фраггер. Конкретные обязанности зависят от договорённостей команды.</p>`}`;if(step===2)content=`<div class="field-label">Что сейчас чаще вызывает вопросы?</div>${options('focus',draft.team==='Solo'?FOCI.filter(x=>x!=='Коммуникация'):FOCI)}`;if(step===3)content=`${options('minutes',[20,40,60,90])}<div class="notice">Дисциплина — выполнять осмысленный план и честно разбирать результат. Отдых тоже часть работы. Здесь нет штрафа за пропущенный день.</div><p class="fine">Первая версия сохраняет данные в этом браузере. В разделе «Тренер» можно включить локальную языковую модель для свободного общения. Она требует скачивания и совместимого устройства.</p>`;$('#onboarding').innerHTML=`<div class="dialog-inner"><div class="dialog-top"><span>ТВОЯ ОТПРАВНАЯ ТОЧКА / ${step+1} ИЗ 4</span><button class="close" data-action="close-dialog" aria-label="Закрыть опрос">${icon('close')}</button></div><div class="steps">${[0,1,2,3].map(i=>`<span class="${i<=step?'current':''}"></span>`).join('')}</div><h2 id="onboard-title">${titles[step]}</h2><p>${desc[step]}</p>${content}<p class="error" id="onboard-error" role="alert"></p><div class="dialog-actions"><button class="btn ghost" data-action="previous-step">${step?'← Назад':'Позже'}</button><button class="btn small" data-action="next-step">${step===3?'Создать мой план':'Продолжить'} ${icon('arrow')}</button></div></div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(b.hasAttribute('data-checkin-edit')){editingCheckin=true;render();}if(a==='start'){state.profile?go('dashboard'):onboarding();}if(a==='edit-profile')onboarding(true);if(a==='close-dialog')$('#onboarding').close();if(a==='previous-step'){if(!step)$('#onboarding').close();else{step--;renderOnboarding();}}if(a==='next-step'){if(step===0){draft.nick=$('#nick').value.trim();if(!draft.nick){$('#onboard-error').textContent='Укажи никнейм, чтобы продолжить.';$('#nick').focus();return;}}if(step<3){step++;renderOnboarding();}else if(validProfile(draft)){state.profile={...draft,minutes:Number(draft.minutes)};save();$('#onboarding').close();if(location.hash==='#dashboard')render();else go('dashboard');toast('Профиль готов. Начнём с одной задачи.');}}if(b.dataset.option){if($('#nick'))draft.nick=$('#nick').value;draft[b.dataset.option]=b.dataset.option==='minutes'?Number(b.dataset.value):b.dataset.value;if(draft.team==='Solo'&&draft.focus==='Коммуникация')draft.focus='Ротации';if(draft.team==='Duo'&&draft.role==='Саппорт')draft.role='Фраггер';renderOnboarding();}if(b.dataset.toggle){const key=dayKey(),id=b.dataset.toggle;const done=state.completed[key]||[];state.completed[key]=done.includes(id)?done.filter(x=>x!==id):[...done,id];save();render();}if(b.dataset.prompt){$('#chat-message').value=b.dataset.prompt;$('#chat-message').focus();}if(b.dataset.journalFilter){journalFilter=b.dataset.journalFilter;render();}if(b.dataset.pinSession!==undefined){const item=state.sessions[Number(b.dataset.pinSession)];if(item){item.pinned=!item.pinned;if(save())render();}}if(b.dataset.deleteSession!==undefined&&confirm('Удалить эту запись?')){state.sessions.splice(Number(b.dataset.deleteSession),1);save();render();}if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`nextdrop-${dayKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(a==='reset'&&confirm('Удалить весь профиль, журнал и диалог из этого браузера?')){try{localStorage.removeItem('nextdrop.v1');}catch{}resetAI();state=freshState();resetEvidence();go('home');toast('Локальные данные удалены.');}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='checkin-form'){const sleep=Number(d.get('sleep')),energy=Number(d.get('energy')),minutes=Number(d.get('minutes'));if(!Number.isFinite(sleep)||sleep<0||sleep>24||!Number.isInteger(energy)||energy<1||energy>5||![20,40,60,90].includes(minutes))return;state.checkins[dayKey()]={sleep,energy,minutes};if(save()){editingCheckin=false;render();toast('Задача на сегодня обновлена.');}}if(f.id==='review-form'){state.review={stage:d.get('stage'),note:String(d.get('note')).trim()};if(save())toast('Описание сохранено. Файл остаётся только в текущем просмотре.');}if(f.id==='session-form'){const type=String(d.get('type')),note=String(d.get('note')||'').trim(),isNote=['Ошибка / вывод','Полезная информация'].includes(type);const matches=isNote?0:Number(d.get('matches')),early=isNote?0:Number(d.get('early'));if(!note||!Number.isInteger(matches)||!Number.isInteger(early)||matches<0||early<0||early>matches){$('#session-error').textContent='Проверь запись и числа матчей: ранних вылетов не может быть больше сыгранных матчей.';return;}state.sessions.unshift({date:d.get('date'),type,matches,early,note,pinned:d.get('pinned')==='yes'});state.sessions=state.sessions.slice(0,365);if(save()){render();toast('Запись сохранена в журнале.');}}if(f.id==='stats-form'){for(const k of ['pr','earnings','events'])state.stats[k]=d.get(k)===''?null:Number(d.get(k));if(save())toast('Показатели сохранены как введённые тобой.');}if(f.id==='links-form'){for(const k of ['tracker','osirion']){const val=String(d.get(k)).trim();if(val&&!safeProfileURL(val,k)){$('#links-error').textContent=`Нужна HTTPS-ссылка на ${k==='tracker'?'fortnitetracker.com':'osirion.gg'}.`;return;}}for(const k of ['tracker','osirion'])state.profile[k]=String(d.get(k)).trim();save();render();toast('Ссылки сохранены.');}});
document.addEventListener('change',async e=>{if(e.target.id==='session-type'){const note=['Ошибка / вывод','Полезная информация'].includes(e.target.value);const fields=$('#journal-match-fields');if(fields)fields.hidden=note;const label=$('#journal-note-label'),area=$('#session-note');if(label)label.textContent=e.target.value==='Полезная информация'?'Что полезного хочешь запомнить перед игрой?':e.target.value==='Ошибка / вывод'?'Какая ошибка повторилась? Что проверишь в следующий раз?':'Что произошло? Какой вывод из этой сессии?';if(area)area.placeholder=e.target.value==='Полезная информация'?'Например: перед турниром проверить формат очков и лутпул.':'Коротко и конкретно: что заметил, что изменишь.';}if(e.target.id==='import'){const file=e.target.files[0];if(!file)return;if(file.size>2000000){toast('Копия слишком большая: максимум 2 МБ.');return;}try{const incoming=parseState(await file.text());if(confirm(`Заменить текущие данные профилем ${incoming.profile.nick}?`)){resetAI();state=incoming;save();render();toast('Данные восстановлены.');}}catch(err){toast('Не удалось прочитать копию: '+err.message);}}if(e.target.id==='attachment'){const file=e.target.files[0];if(!file)return;const preview=$('#file-preview');preview.replaceChildren();if(mediaUrl){URL.revokeObjectURL(mediaUrl);mediaUrl=null;}if(file.size>100*1024*1024){toast('Выбери отдельный фрагмент до 100 МБ.');e.target.value='';return;}const name=document.createElement('p');name.className='fine';name.textContent=`${file.name} · ${(file.size/1048576).toFixed(1)} МБ · только локальный просмотр`;preview.append(name);if(/\.(mp4|webm)$/i.test(file.name)&&file.type.startsWith('video/')){mediaUrl=URL.createObjectURL(file);const v=document.createElement('video');v.controls=true;v.src=mediaUrl;v.className='media-preview';v.preload='metadata';v.addEventListener('error',()=>toast('Браузер не смог воспроизвести этот формат.'));preview.append(v);}else if(/^image\/(png|jpeg|webp)$/.test(file.type)){mediaUrl=URL.createObjectURL(file);const img=document.createElement('img');img.src=mediaUrl;img.alt='Прикреплённый скриншот';img.className='media-preview';preview.append(img);}else{const note=document.createElement('p');note.className='notice';note.textContent=/\.replay$/i.test(file.name)?'Файл выбран, но парсер .replay ещё не подключён. Для просмотра добавь видеофрагмент.':'Этот формат не поддерживается для просмотра. Выбери MP4, WebM, PNG, JPEG или WebP.';preview.append(note);}}});
