function refreshDailyView(){if(renderedDay!==dayKey())render();}window.addEventListener('focus',refreshDailyView);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDailyView();});setInterval(refreshDailyView,60000);window.addEventListener('hashchange',()=>{render();if(!['#how','#principles','#faq'].includes(location.hash))window.scrollTo(0,0);});render();if(loadError)toast('Сохранение не удалось прочитать. Исходная запись не удалена.');
